* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

body {
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  background: #1a1a2e;
  color: #e0e0e0;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 1rem;
}

.game-card {
  background: #16213e;
  border: 4px solid #0f3460;
  border-radius: 0;
  padding: 1.5rem;
  max-width: 800px;
  width: 100%;
  box-shadow: 0 0 0 4px #e94560, 0 0 20px rgba(233, 69, 96, 0.3);
  text-align: center;
}

h1 {
  font-size: 1.5rem;
  margin-bottom: 1rem;
  color: #e94560;
  text-transform: uppercase;
  letter-spacing: 2px;
  text-shadow: 2px 2px 0 #0f3460;
}

.status {
  font-size: 1.25rem;
  margin-bottom: 1.5rem;
  min-height: 2rem;
  font-weight: bold;
  color: #e0e0e0;
}

.track {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 6px;
  margin-bottom: 1.5rem;
  padding: 8px;
  background: #0f3460;
  border: 3px solid #e94560;
}

.square {
  aspect-ratio: 1;
  background: #1a1a2e;
  border: 2px solid #0f3460;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.75rem;
  font-weight: bold;
  color: #555;
  position: relative;
  image-rendering: pixelated;
}

.square.finish {
  background: #e94560;
  color: #16213e;
  border-color: #e94560;
}

.token {
  width: 60%;
  height: 60%;
  border-radius: 0;
  position: absolute;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.6rem;
  font-weight: bold;
  color: #fff;
  box-shadow: 2px 2px 0 rgba(0,0,0,0.5);
}

.token.p1 {
  background: #e94560;
  left: 10%;
  top: 10%;
}

.token.p2 {
  background: #4ecdc4;
  right: 10%;
  bottom: 10%;
  color: #1a1a2e;
}

.controls {
  display: flex;
  gap: 1rem;
  justify-content: center;
  margin-bottom: 1rem;
  flex-wrap: wrap;
}

.btn {
  font-family: inherit;
  font-size: 1.125rem;
  font-weight: bold;
  padding: 0.75rem 2rem;
  border: 3px solid #e94560;
  background: #0f3460;
  color: #e0e0e0;
  cursor: pointer;
  text-transform: uppercase;
  letter-spacing: 1px;
  transition: background 0.1s, transform 0.1s;
  image-rendering: pixelated;
}

.btn:hover {
  background: #e94560;
  color: #16213e;
}

.btn:focus-visible {
  outline: 3px solid #4ecdc4;
  outline-offset: 2px;
}

.btn:active {
  transform: translate(2px, 2px);
  box-shadow: none;
}

.btn:disabled {
  opacity: 0.5;
  cursor: not-allowed;
  background: #0f3460;
  color: #888;
  border-color: #555;
}

.die-area {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  font-size: 1.125rem;
}

.die-value {
  display: inline-block;
  min-width: 2.5rem;
  padding: 0.25rem 0.5rem;
  background: #0f3460;
  border: 2px solid #e94560;
  font-weight: bold;
  font-size: 1.25rem;
  color: #e0e0e0;
  text-align: center;
}

@media (max-width: 480px) {
  .game-card {
    padding: 1rem;
  }
  h1 {
    font-size: 1.25rem;
  }
  .track {
    gap: 4px;
    padding: 4px;
  }
  .square {
    font-size: 0.6rem;
  }
  .token {
    font-size: 0.5rem;
  }
  .btn {
    padding: 0.6rem 1.2rem;
    font-size: 1rem;
  }
}

const TRACK_SIZE = 20;
const PLAYER_1 = 'Player 1';
const PLAYER_2 = 'Player 2';

const state = {
  positions: { [PLAYER_1]: 0, [PLAYER_2]: 0 },
  currentPlayer: PLAYER_1,
  gameOver: false,
  lastRoll: null
};

const trackEl = document.getElementById('track');
const statusEl = document.getElementById('status');
const rollBtn = document.getElementById('rollBtn');
const playAgainBtn = document.getElementById('playAgainBtn');
const dieValueEl = document.getElementById('dieValue');

function createTrack() {
  trackEl.innerHTML = '';
  for (let i = 1; i <= TRACK_SIZE; i++) {
    const square = document.createElement('div');
    square.className = 'square';
    square.setAttribute('role', 'listitem');
    square.setAttribute('aria-label', `Square ${i}`);
    if (i === TRACK_SIZE) square.classList.add('finish');
    square.textContent = i;
    square.dataset.index = i;
    trackEl.appendChild(square);
  }
}

function renderTokens() {
  document.querySelectorAll('.token').forEach(t => t.remove());
  for (const player of [PLAYER_1, PLAYER_2]) {
    const pos = state.positions[player];
    if (pos > 0) {
      const square = trackEl.querySelector(`[data-index="${pos}"]`);
      if (square) {
        const token = document.createElement('span');
        token.className = `token ${player === PLAYER_1 ? 'p1' : 'p2'}`;
        token.textContent = player === PLAYER_1 ? 'P1' : 'P2';
        token.setAttribute('aria-label', `${player} token`);
        square.appendChild(token);
      }
    }
  }
}

function updateUI() {
  if (state.gameOver) {
    const winner = state.positions[PLAYER_1] >= TRACK_SIZE ? PLAYER_1 : PLAYER_2;
    statusEl.textContent = `${winner} wins!`;
    rollBtn.disabled = true;
    playAgainBtn.hidden = false;
  } else {
    statusEl.textContent = `${state.currentPlayer}'s turn`;
    rollBtn.disabled = false;
    playAgainBtn.hidden = true;
  }
  dieValueEl.textContent = state.lastRoll !== null ? state.lastRoll : '–';
  renderTokens();
}

function rollDice() {
  if (state.gameOver) return;
  const roll = Math.floor(Math.random() * 6) + 1;
  state.lastRoll = roll;
  const player = state.currentPlayer;
  state.positions[player] = Math.min(state.positions[player] + roll, TRACK_SIZE);
  if (state.positions[player] >= TRACK_SIZE) {
    state.gameOver = true;
  } else {
    state.currentPlayer = player === PLAYER_1 ? PLAYER_2 : PLAYER_1;
  }
  updateUI();
}

function resetGame() {
  state.positions = { [PLAYER_1]: 0, [PLAYER_2]: 0 };
  state.currentPlayer = PLAYER_1;
  state.gameOver = false;
  state.lastRoll = null;
  updateUI();
}

function init() {
  createTrack();
  updateUI();
  rollBtn.addEventListener('click', rollDice);
  playAgainBtn.addEventListener('click', resetGame);
}

init();
